import {builderStyles,builderSections,builderTemplates} from './website-builder-library.js?upgrade=2';
const $=id=>document.getElementById(id);let projectId='',revision=0,busy=false,dirty=false,publication=null;
const safePolicy="default-src 'none'; img-src https: data: blob:; style-src 'unsafe-inline'; font-src https: data:; base-uri 'none'; form-action 'none'; frame-src 'none'";
const esc=value=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const editor=grapesjs.init({container:'#editor',height:'100%',storageManager:false,allowScripts:false,parser:{optionsHtml:{allowScripts:false,allowUnsafeAttr:false}},deviceManager:{devices:[{name:'Desktop',width:''},{name:'Tablet',width:'768px',widthMedia:'992px'},{name:'Phone',width:'375px',widthMedia:'480px'}]},blockManager:{blocks:[...builderSections.map(section=>({id:section.id,label:section.label,category:section.category,content:'<style>'+builderStyles+'</style>'+section.content})),{id:'image',label:'Image',category:'Content',content:{type:'image'}}]}});
const starter=builderTemplates[0].html;
editor.on('update',()=>{dirty=true;controls();});
editor.on('undo',()=>{dirty=true;controls();});editor.on('redo',()=>{dirty=true;controls();});
editor.on('device:select',controls);editor.on('load',controls);
editor.setComponents(starter);editor.setStyle(builderStyles);editor.UndoManager.clear();dirty=false;
for(const section of builderSections){const option=document.createElement('option');option.value=section.id;option.textContent=section.label;$('section-select').append(option);}
$('section-select').value=builderSections[0].id;
for(const template of builderTemplates){
 const button=document.createElement('button');button.type='button';button.className='builder-template builder-template-'+template.theme;button.dataset.template=template.id;
 button.innerHTML='<div class="builder-template-thumbnail"><span>YOUR BRAND / YOUR VISION</span><strong>'+esc(template.name)+'</strong><span>EDIT · PREVIEW · PUBLISH</span></div><div class="builder-template-info"><small>'+esc(template.kind)+'</small><strong>'+esc(template.name)+'</strong><span>'+esc(template.description)+'</span><b>Use this template ↗</b></div>';
 button.onclick=()=>{if(busy)return;if(dirty&&!confirm('Start a new draft and discard your unsaved edits?'))return;newProject(template);$('template-dialog').close();};$('template-list').append(button);
}
$('templates').onclick=()=>{if(!busy)$('template-dialog').showModal();};$('template-close').onclick=()=>$('template-dialog').close();
$('insert-section').onclick=()=>{if(busy)return;const section=builderSections.find(item=>item.id===$('section-select').value);if(!section)return;editor.addStyle(builderStyles);const added=editor.addComponents(section.content);if(added[0])editor.select(added[0]);dirty=true;controls();$('status').textContent=section.label+' added. Drag it into position and edit its content.';};
$('undo').onclick=()=>{if(!busy&&editor.UndoManager.hasUndo())editor.UndoManager.undo();};$('redo').onclick=()=>{if(!busy&&editor.UndoManager.hasRedo())editor.UndoManager.redo();};
for(const device of ['Desktop','Tablet','Phone'])$('device-'+device.toLowerCase()).onclick=()=>{if(!busy){editor.setDevice(device);controls();}};
$('canvas-focus').onclick=()=>{if(busy)return;const focused=document.body.classList.toggle('builder-focus');$('canvas-focus').setAttribute('aria-pressed',String(focused));editor.refresh();};

function output(){return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="'+esc(safePolicy)+'"><title>'+esc($('project-name').value)+'</title><style>'+editor.getCss().replace(/<\/style/gi,'<\\/style')+'</style></head><body>'+editor.getHtml()+'</body></html>';}
function controls(){
 editor.getContainer().inert=busy;$('project-name').disabled=busy;
 for(const id of ['save','new','projects','preview','export','publication-refresh','publish-close','templates','template-close','section-select','insert-section','canvas-focus','device-desktop','device-tablet','device-phone'])$(id).disabled=busy;
 for(const button of $('template-list').children)button.disabled=busy;
 $('undo').disabled=busy||!editor.UndoManager.hasUndo();$('redo').disabled=busy||!editor.UndoManager.hasRedo();
 for(const device of ['Desktop','Tablet','Phone'])$('device-'+device.toLowerCase()).setAttribute('aria-pressed',String(editor.getDevice()===device));
 $('save-state').textContent=busy?'Working…':dirty?'Unsaved changes':projectId?'Saved · revision '+revision:'New draft';$('save-state').dataset.dirty=String(dirty);
 $('publish').disabled=busy||dirty||!projectId||!publication;$('publish-confirm').disabled=busy||dirty||!$('publish-approved').checked;$('unpublish').disabled=busy||!publication?.published;
}
function publicationView(){const active=publication?.published===true,link=$('published-link');link.hidden=!active;if(active)link.href=publication.url;$('publication-status').textContent=!projectId?'Save a draft to create a public website.':!publication?'Publication status unavailable. Check it before publishing.':active?'Public website · saved revision '+publication.projectRevision+(publication.projectRevision!==revision?' · newer draft changes need publication.':'.'):'Private draft · no public page is available.';controls();}
async function loadPublication(){publication=null;publicationView();if(!projectId)return;const r=await fetch('/api/builder/projects/'+projectId+'/publication',{cache:'no-store'}),data=await r.json();if(!r.ok)throw Error(data.error||'Publication status unavailable.');publication=data;publicationView();}
async function list(){const r=await fetch('/api/builder/projects',{cache:'no-store'}),data=await r.json();if(!r.ok)throw Error(data.error||'Saved projects could not be loaded.');const option=document.createElement('option');option.value='';option.textContent='New project';$('projects').replaceChildren(option);for(const row of data.projects){const o=document.createElement('option');o.value=row.id;o.textContent=row.name;$('projects').append(o);}$('projects').value=projectId;}
$('project-name').addEventListener('input',()=>{dirty=true;controls();});
$('save').onclick=async()=>{if(busy)return;if(!$('project-name').value.trim()){$('status').textContent='Enter a project name.';return;}busy=true;controls();try{const body={name:$('project-name').value,projectData:editor.getProjectData(),html:editor.getHtml(),css:editor.getCss(),revision};const r=await fetch('/api/builder/projects'+(projectId?'/'+projectId:''),{method:projectId?'PUT':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}),data=await r.json();if(!r.ok)throw Error(data.error||'Save failed.');projectId=data.id;revision=data.revision;dirty=false;$('status').textContent='Website saved to your account. Publishing is a separate step.';await list();await loadPublication();}catch(e){$('status').textContent=e.message;}finally{busy=false;controls();}};
$('projects').onchange=async()=>{if(busy)return;const selected=$('projects').value;if(dirty&&!confirm('Open another project and discard unsaved edits?')){$('projects').value=projectId;return;}if(!selected){newProject();return;}busy=true;controls();try{const r=await fetch('/api/builder/projects/'+selected,{cache:'no-store'}),data=await r.json();if(!r.ok)throw Error(data.error||'Project could not be loaded.');editor.loadProjectData(data.projectData);editor.UndoManager.clear();$('project-name').value=data.name;projectId=data.id;revision=data.revision;dirty=false;$('status').textContent='Saved website opened.';await loadPublication();}catch(e){$('status').textContent=e.message;$('projects').value=projectId;}finally{busy=false;controls();}};
function newProject(template=builderTemplates[0]){projectId='';revision=0;publication=null;editor.loadProjectData({pages:[{component:template.html}],styles:[],assets:[]});editor.setStyle(template.css);editor.UndoManager.clear();$('project-name').value='My '+template.name.toLowerCase()+' website';$('projects').value='';dirty=true;publicationView();$('status').textContent=template.name+' draft ready. Replace the placeholder text, add your images and save to your account.';}
$('new').onclick=()=>{if(!dirty||confirm('Start a new project and discard unsaved edits?'))newProject();};
$('preview').onclick=()=>{$('preview-frame').srcdoc=output();$('preview-dialog').showModal();};$('preview-close').onclick=()=>{$('preview-dialog').close();$('preview-frame').srcdoc='';};
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([output()],{type:'text/html'})),a=document.createElement('a');a.href=url;a.download='website.html';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='HTML exported. Review the website before publishing.';};
$('publish').onclick=()=>{if(busy||dirty||!projectId||!publication)return;$('publish-approved').checked=false;$('publish-review-frame').srcdoc=output();$('publish-dialog').showModal();controls();};
$('publish-close').onclick=()=>{$('publish-dialog').close();$('publish-review-frame').srcdoc='';};
$('publish-approved').addEventListener('change',controls);
async function changePublication(method){if(busy||!projectId||!publication)return;busy=true;controls();try{const r=await fetch('/api/builder/projects/'+projectId+'/publication',{method,headers:{'content-type':'application/json'},body:JSON.stringify({revision,publicationRevision:publication.publicationRevision,approved:method==='POST'&&$('publish-approved').checked})}),data=await r.json();if(!r.ok)throw Error(data.error||'Publication failed.');publication=data;publicationView();$('publish-dialog').close();$('publish-review-frame').srcdoc='';$('status').textContent=method==='POST'?'Your saved website is public. Open its link to view it.':'Public website removed. Your saved draft is retained.';}catch(e){$('status').textContent=e.message;if($('publish-dialog').open)$('publish-feedback').textContent=e.message;}finally{busy=false;controls();}}
$('publish-confirm').onclick=()=>{if(!dirty&&$('publish-approved').checked)changePublication('POST');};
$('unpublish').onclick=()=>{if(publication?.published&&confirm('Remove this public page? Your private draft will be kept.'))changePublication('DELETE');};
$('publication-refresh').onclick=async()=>{if(busy)return;busy=true;controls();try{await loadPublication();}catch(e){$('status').textContent=e.message;}finally{busy=false;controls();}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
document.addEventListener('keydown',event=>{if(event.defaultPrevented||event.isComposing)return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();if(!busy&&!document.querySelector('dialog[open]'))$('save').click();}});
publicationView();try{await list();$('status').textContent='Choose a template or add sections. Edit your content, save a draft, then preview and publish.';}catch(e){$('status').textContent=e.message;}
